                                     CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01_evidence_type_check') || ' AND ' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01_data_class_check') || ' AND ' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01m_type_class_pairing_check') || ') AS ok FROM (VALUES (' || quote_literal('dictionary_field_presence_fact') || '::text' || ', ' || quote_literal('source_derived_aggregate') || '::text' || ')) AS v(evidence_type, data_class)', true, true, '')))[1]::text) = 'false' THEN NULL ELSE 'dictionary_field_presence_fact/source_derived_aggregate expected rejected' END,
                                     CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01_evidence_type_check') || ' AND ' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01_data_class_check') || ' AND ' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01m_type_class_pairing_check') || ') AS ok FROM (VALUES (' || quote_literal('source_record_count_measurement') || '::text' || ', ' || quote_literal('organization_committed_metadata') || '::text' || ')) AS v(evidence_type, data_class)', true, true, '')))[1]::text) = 'false' THEN NULL ELSE 'source_record_count_measurement/organization_committed_metadata expected rejected' END,
                                     CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01_evidence_type_check') || ' AND ' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01_data_class_check') || ' AND ' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.evidence_items') AND conname = 'evidence_items_p2_01m_type_class_pairing_check') || ') AS ok FROM (VALUES (' || quote_literal('source_value_statement') || '::text' || ', ' || quote_literal('source_derived_aggregate') || '::text' || ')) AS v(evidence_type, data_class)', true, true, '')))[1]::text) = 'false' THEN NULL ELSE 'source_value_statement/source_derived_aggregate expected rejected' END) AS raw) r
      CROSS JOIN LATERAL (SELECT nullif(r.raw, '') AS bad) m
  UNION ALL
